11: 
12: export const CONTRACT_TRANSITIONS: Record<ContractStatus, ContractStatus[]> = {
13:   DRAFT: ["INFORMATION_REQUIRED", "READY_FOR_ROUTING", "CANCELLED"],
14:   INFORMATION_REQUIRED: ["READY_FOR_ROUTING", "CANCELLED"],
