35:   ASSIGNED: ["UNDER_REVIEW", "CANCELLED"],
36:   UNDER_REVIEW: ["INFORMATION_REQUESTED", "CHANGES_REQUESTED", "READY_FOR_VALIDATION", "REJECTED", "CANCELLED"],
37:   INFORMATION_REQUESTED: ["UNDER_REVIEW", "CANCELLED"],
38:   CHANGES_REQUESTED: ["UNDER_REVIEW", "CANCELLED"],
39:   READY_FOR_VALIDATION: ["VALIDATED", "UNDER_REVIEW", "CANCELLED"],
40:   VALIDATED: ["SIGNATURE_PENDING", "COMPLETED", "CANCELLED"],
41:   SIGNATURE_PENDING: ["SIGNED", "CANCELLED"],
42:   SIGNED: ["COMPLETED"],
43:   REJECTED: ["CANCELLED"],
44:   CANCELLED: [],
45:   COMPLETED: [],
46: };
47: 
48: export class InvalidStateTransitionError extends Error {
49:   constructor(
50:     readonly from: string,
51:     readonly to: string,
52:   ) {
53:     super(`Invalid state transition: ${from} → ${to}`);
54:     this.name = "InvalidStateTransitionError";
55:   }
56: }
57: 
58: export function canTransition(from: ContractStatus, to: ContractStatus): boolean {
59:   return CONTRACT_TRANSITIONS[from]?.includes(to) ?? false;
60: }
61: 
62: export function allowedTransitions(from: ContractStatus): ContractStatus[] {
63:   return CONTRACT_TRANSITIONS[from] ?? [];
64: }
65: 
66: export function assertTransition(from: ContractStatus, to: ContractStatus): void {
67:   if (from === to) return;
68:   if (!canTransition(from, to)) {
69:     logger.error(LOG_EVENTS.stateTransitionRejected, { from, to, allowed: allowedTransitions(from) });
70:     throw new InvalidStateTransitionError(from, to);
