import type { Metadata } from "next";
import { ShieldCheck } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { VerifyIntakeForm, type VerifyIntakeConfig } from "@/components/guest/verify-intake";
import { getServerI18n } from "@/lib/i18n/server";
import { verifyMaxBytes, verifyRetentionDays, VERIFICATION_MIME_LABELS } from "@/lib/verification/rules";

/**
 * Verification journey (§8b) — "faire vérifier un document existant".
 *
 * No form, no questionnaire: the visitor picks a file and a tier and that is
 * the whole screen. The left column carries the sample-free upload + tier
 * choice; the right column is an empty, clearly labelled placeholder until a
 * file is chosen — a sample contract is never displayed here. Safety copy
 * (accepted types, maximum size, private storage and retention) is shown
 * before the upload, and every rule is enforced again server-side.
 */

const EXTENSIONS_BY_MIME: Record<string, string> = {
  "application/pdf": ".pdf",
  "application/msword": ".doc",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document": ".docx",
  "image/jpeg": ".jpg,.jpeg",
  "image/png": ".png",
  "image/webp": ".webp",
  "image/heic": ".heic",
};

export async function generateMetadata(): Promise<Metadata> {
  const { d } = await getServerI18n();
  const t = d.public.verify;

  return {
    title: t.metaTitle,
    description: t.metaDescription,
    alternates: { canonical: "/verify" },
  };
}

export default async function VerifyPage() {
  const { locale, d } = await getServerI18n();
  const t = d.public.verify;

  const maxBytes = verifyMaxBytes();

  const maxSizeText =
    locale === "ar"
      ? `${Math.ceil(maxBytes / (1024 * 1024))} م.ب`
      : `${Number.isInteger(maxBytes / (1024 * 1024)) ? maxBytes / (1024 * 1024) : (maxBytes / (1024 * 1024)).toFixed(1).replace(".", ",")} Mo`;

  const config: VerifyIntakeConfig = {
    maxBytes,
    maxSizeText,
    accept: Object.entries(EXTENSIONS_BY_MIME)
      .filter(([mime]) => mime in VERIFICATION_MIME_LABELS)
      .map(([, extensions]) => extensions)
      .join(","),
  };

  return (
    <div className="mx-auto w-full max-w-5xl px-4 py-12 sm:px-6 lg:py-16">
      <div className="mb-10 space-y-3 text-center">
        <span className="font-mono text-xs font-bold uppercase tracking-widest text-accent-strong" dir="auto">
          {t.eyebrow}
        </span>
        <h1 className="text-3xl font-bold tracking-tight sm:text-4xl" dir="auto">
          {t.title}
        </h1>
        <p className="mx-auto max-w-xl text-sm text-muted-foreground" dir="auto">
          {t.subtitle}
        </p>
      </div>

      <VerifyIntakeForm
        labels={t}
        config={config}
        retentionNote={t.retentionNote.replace("{days}", String(verifyRetentionDays()))}
        delayHint={{ ASSISTED: t.delayAssisted, LAWYER: t.delayLawyer }}
        priceUnit={locale === "ar" ? "دون ضريبة" : "HT"}
      />

      {/* What the verification produces — plain words, no legal-advice claims. */}
      <section className="mt-14" aria-labelledby="verify-produces">
        <h2 id="verify-produces" className="text-lg font-semibold" dir="auto">
          {t.producesTitle}
        </h2>
        <div className="mt-4 grid gap-4 sm:grid-cols-2">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-base" dir="auto">
                <ShieldCheck className="h-4 w-4 text-primary" aria-hidden />
                {t.tierAssistedTitle}
              </CardTitle>
              <CardDescription dir="auto">{t.delayAssisted}</CardDescription>
            </CardHeader>
            <CardContent className="text-sm text-muted-foreground" dir="auto">
              {t.producesAssisted}
            </CardContent>
          </Card>
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-base" dir="auto">
                <ShieldCheck className="h-4 w-4 text-primary" aria-hidden />
                {t.tierLawyerTitle}
              </CardTitle>
              <CardDescription dir="auto">{t.delayLawyer}</CardDescription>
            </CardHeader>
            <CardContent className="text-sm text-muted-foreground" dir="auto">
              {t.producesLawyer}
            </CardContent>
          </Card>
        </div>
      </section>
    </div>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { Check, FileText, ReceiptText, ShieldCheck } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { getServerI18n } from "@/lib/i18n/server";
import { verifyRetentionDays } from "@/lib/verification/rules";
import { resolveVerificationIntake } from "@/lib/verification/service";

/**
 * Verification confirmation (§8b).
 *
 * Reached with the one-time bearer token the upload response issued, this page
 * shows exactly what was received — file name, size, chosen tier, expected
 * delay and the amount due at the next step — plus the retention promise. It
 * never claims the report is delivered already: the intake is still RECEIVED
 * until the payment step (next phase) opens the workflow.
 */

export const metadata: Metadata = {
  title: "Vérification reçue — dossier",
  robots: { index: false },
};

export default async function VerifyConfirmationPage({ params }: { params: Promise<{ token: string }> }) {
  const { token } = await params;
  const [{ locale, d }, intake] = await Promise.all([getServerI18n(), resolveVerificationIntake(token)]);
  const t = d.public.verify;

  if (!intake) {
    return (
      <div className="mx-auto w-full max-w-lg px-4 py-20 text-center sm:px-6">
        <h1 className="text-2xl font-bold" dir="auto">
          {t.notFoundTitle}
        </h1>
        <p className="mt-3 text-sm text-muted-foreground" dir="auto">
          {t.notFoundBody}
        </p>
        <Button asChild className="mt-6">
          <Link href="/verify">
            <span dir="auto">{t.verifyAnother}</span>
          </Link>
        </Button>
      </div>
    );
  }

  const isLawyer = intake.tier === "LAWYER";
  const tierTitle = isLawyer ? t.tierLawyerTitle : t.tierAssistedTitle;
  const price = isLawyer ? t.tierLawyerPrice : t.tierAssistedPrice;
  const delay = locale === "ar" ? (isLawyer ? t.delayLawyer : t.delayAssisted) : isLawyer ? t.delayLawyer : t.delayAssisted;
  const sizeText = locale === "ar" ? `${(intake.sizeBytes / (1024 * 1024)).toFixed(2).replace(".", ",")} م.ب` : undefined;
  const frSizeText = `${(intake.sizeBytes / (1024 * 1024)).toFixed(2).replace(".", ",")} Mo`;

  return (
    <div className="mx-auto w-full max-w-3xl px-4 py-12 sm:px-6 lg:py-16">
      <div className="mb-8 space-y-3 text-center">
        <span className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300">
          <Check className="h-6 w-6" aria-hidden />
        </span>
        <h1 className="text-2xl font-bold tracking-tight sm:text-3xl" dir="auto">
          {t.confirmationTitle}
        </h1>
        <p className="mx-auto max-w-xl text-sm text-muted-foreground" dir="auto">
          {t.confirmationSubtitle}
        </p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-lg" dir="auto">
            <ReceiptText className="h-5 w-5 text-primary" aria-hidden />
            {t.referenceLabel}
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-5">
          <p className="rounded-lg border border-dashed border-border bg-muted/30 px-4 py-3 text-center font-mono text-lg font-bold tracking-wide">
            {intake.reference}
          </p>

          <dl className="space-y-3 text-sm">
            <div className="flex items-start justify-between gap-4">
              <dt className="text-muted-foreground" dir="auto">
                {t.fileLabel}
              </dt>
              <dd className="flex min-w-0 items-center gap-2 text-right" dir="auto">
                <FileText className="h-4 w-4 shrink-0 text-muted-foreground" aria-hidden />
                <span className="break-all">{intake.filename}</span>
              </dd>
            </div>
            <div className="flex items-center justify-between gap-4">
              <dt className="text-muted-foreground" dir="auto">
                {t.sizeLabel}
              </dt>
              <dd dir="auto">{sizeText ?? frSizeText}</dd>
            </div>
            <div className="flex items-center justify-between gap-4">
              <dt className="text-muted-foreground" dir="auto">
                {t.tierLabel}
              </dt>
              <dd dir="auto">{tierTitle}</dd>
            </div>
            <div className="flex items-center justify-between gap-4">
              <dt className="text-muted-foreground" dir="auto">
                {t.delayLabel}
              </dt>
              <dd dir="auto">{delay}</dd>
            </div>
            <div className="flex items-center justify-between gap-4">
              <dt className="text-muted-foreground" dir="auto">
                {t.priceLabelConfirm}
              </dt>
              <dd className="font-semibold">
                {price}{" "}
                <span className="text-xs font-normal text-muted-foreground" dir="auto">
                  {locale === "ar" ? "دون ضريبة" : "HT"}
                </span>
              </dd>
            </div>
            <div className="flex items-center justify-between gap-4">
              <dt className="text-muted-foreground" dir="auto">
                {t.statusLabel}
              </dt>
              <dd className="flex items-center gap-1.5 font-medium text-emerald-700 dark:text-emerald-400" dir="auto">
                <span className="relative flex h-2 w-2">
                  <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-emerald-500 opacity-60" />
                  <span className="relative inline-flex h-2 w-2 rounded-full bg-emerald-600" />
                </span>
                {t.statusReceived}
              </dd>
            </div>
          </dl>

          <p className="flex items-start gap-2 rounded-lg border border-border bg-muted/30 px-3 py-2.5 text-xs text-muted-foreground" dir="auto">
            <ShieldCheck className="mt-0.5 h-4 w-4 shrink-0 text-primary" aria-hidden />
            {t.retentionNote.replace("{days}", String(verifyRetentionDays()))}
          </p>
        </CardContent>
      </Card>

      <div className="mt-6 text-center">
        <Button asChild variant="outline">
          <Link href="/verify">
            <span dir="auto">{t.verifyAnother}</span>
          </Link>
        </Button>
      </div>
    </div>
  );
}

