/** VAT rate, configurable — Morocco's standard rate is 20 %. */
export const DEFAULT_VAT_RATE = 0.20;
export function vatRate(source = process.env): number {
  const raw = Number(source.VAT_RATE ?? DEFAULT_VAT_RATE);
  return Number.isFinite(raw) && raw >= 0 && raw < 1 ? raw : DEFAULT_VAT_RATE;
}
export interface VatBreakdown { subtotal: number; rate: number; vatAmount: number; total: number; currency: string }
export function withVat(subtotal: number, currency?: string): VatBreakdown {
  const rate = vatRate();
  const vatAmount = Math.round(subtotal * rate * 100) / 100;
  return { subtotal, rate, vatAmount, total: subtotal + vatAmount, currency: currency ?? process.env.PAYMENT_CURRENCY?.trim() ?? "MAD" };
}
```

